WITH valid AS (SELECT id, order_id, shipped_date, delivered_date, cost, status, CASE WHEN cost >= 88 THEN 'High' WHEN cost >= 45 THEN 'Medium' ELSE 'Low' END AS cost_tier FROM shipments WHERE carrier = 'FedEx') SELECT DATE_TRUNC('MONTH', shipped_date) AS activity_month, status, PERCENTILE_APPROX(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END), 0), 2) AS cost_per_delivered, COUNT(CASE WHEN status = 'LOST' THEN 1 END) AS lost_count, ROUND(AVG(cost), 2) AS avg_cost, PERCENTILE_APPROX(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles_2, RANK() OVER (PARTITION BY DATE_TRUNC('MONTH', shipped_date) ORDER BY ROUND(AVG(cost), 2) DESC) AS avg_cost_rank FROM valid GROUP BY DATE_TRUNC('MONTH', shipped_date), status ORDER BY cost_per_delivered
